} from "./health.controller"

@Module({
})
/** Mounts HealthController beside its feature and registers the primary postgres module the probe injects - see the boundary note above. */
export class HealthModule extends ConfigurableModuleClass {
    static register(options: typeof OPTIONS_TYPE = {
    }): DynamicModule {
        const base = super.register(options)
        return {
            ...base, imports: [PostgresqlPrimaryModule.register()], controllers: [HealthController] 
        }
    }
}

